import type { Page } from '@playwright/test';
export class CheckoutPage {
  constructor(private page: Page) {}
  get phone() { return this.page.getByTestId('input-phone'); }
  get placeOrder() {
    const cls = 'css-' + '1a2b3c4';
    return this.page.locator('.' + cls);
  }
}

